/**
 * The app's icons — Phosphor glyphs (MIT) behind the names the code already
 * uses and that categories store in saved data. Content icons are two-tone,
 * an outline over a soft 20 % fill; small UI marks (carets, ×, +) are bold;
 * the tab bar fills the current tab. Path data: glyphData.ts, generated by
 * scripts/gen-glyphs.mjs from scripts/glyphs.json — add an icon there.
 */
import { forwardRef, type ComponentType, type CSSProperties, type SVGProps } from "react";
import { GLYPHS, type GlyphWeight } from "./glyphData";

export interface GlyphProps extends Omit<SVGProps<SVGSVGElement>, "ref" | "children"> {
  size?: number | string;
  /** Kept from the old icon set: 2.2 and up asks for the bold weight */
  strokeWidth?: number | string;
  weight?: GlyphWeight;
  className?: string;
  style?: CSSProperties;
}
export type LucideIcon = ComponentType<GlyphProps>;
export type LucideProps = GlyphProps;

function glyph(name: string, ui: boolean): LucideIcon {
  const G = forwardRef<SVGSVGElement, GlyphProps>(function Glyph({ size = 24, strokeWidth, weight, className, ...rest }, ref) {
    const want: GlyphWeight = weight ?? (className?.includes("fill-current") ? "fill" : ui || Number(strokeWidth) >= 2.2 ? "bold" : "duotone");
    const set = GLYPHS[name];
    const markup = set[want] ?? set.duotone ?? set.bold ?? Object.values(set)[0] ?? "";
    return (
      <svg
        ref={ref}
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 256 256"
        width={size}
        height={size}
        fill="currentColor"
        aria-hidden="true"
        focusable="false"
        className={className ? `glyph ${className}` : "glyph"}
        {...rest}
        dangerouslySetInnerHTML={{ __html: markup }}
      />
    );
  });
  G.displayName = name;
  return G as unknown as LucideIcon;
}

